import {Ajv} from 'ajv';
import type {ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {...unchanged...}
export interface ToolContext {...unchanged...}
export type ToolExecutor = ...unchanged...
export function normalizeToolResponse ...unchanged...
export type ToolDefinitionSource = ...unchanged...
export interface RegisteredTool {...unchanged...}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  // Tool schemas are provider-facing hints: strict mode and format validation stay off, and nothing is coerced, defaulted or additionally forbidden
  private readonly ajv = new Ajv({strict: false, validateFormats: false});
  private readonly staticValidators = new Map<string, ValidateFunction>();
  private readonly dynamicValidators = new WeakMap<object, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private compileSchema(schema: Record<string, unknown>, toolName: string): ValidateFunction {
    try {
      return this.ajv.compile(schema);
    } catch (err) {
      throw new Error(`Tool '${toolName}' has an invalid inputSchema: ${(err as Error).message}`, {cause: err});
    }
  }

  private getValidator(name: string, tool: StoredTool): ValidateFunction {
    if (typeof tool.definitionSource !== 'function') {
      return this.staticValidators.get(name)!;
    }
    const {inputSchema} = tool.definitionSource();
    const cached = this.dynamicValidators.get(inputSchema);
    if (cached) return cached;
    const compiled = this.compileSchema(inputSchema, name);
    this.dynamicValidators.set(inputSchema, compiled);
    return compiled;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    if (typeof definition !== 'function') {
      this.staticValidators.set(resolved.name, this.compileSchema(resolved.inputSchema, resolved.name));
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute});
  }
  ... getters unchanged ...

  /** Validates input against the tool's inputSchema and returns a rejection ToolResponse instead of throwing (specs/hal-engine-tool-input-validation/spec.md) */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }

    const validate = this.getValidator(name, tool);
    if (!validate(input)) {
      const reasons = (validate.errors ?? []).map(e => (e.instancePath ? `${e.instancePath} ${e.message}` : String(e.message)));
      log.warn('tool', 'input rejected by inputSchema', {name, reasons});
      return {result: reasons.join('; ')};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    ...rest unchanged...
  }
}
